package org.apache.commons.jxpath.ri.compiler;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.ValueUtils;
import org.apache.commons.jxpath.ri.compiler.Expression;
import org.apache.commons.jxpath.ri.compiler.ValueIterator;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.util.ValueUtils;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for Expression.iterate(EvalContext context)
 */
public class Expression_iterate_TriageGen2Test {

    @Test
    public void testIterate_ReturnsValueIterator_WhenResultIsEvalContext() {
        // Arrange
        Expression expression = Mockito.mock(Expression.class);
        EvalContext context = mock(EvalContext.class);
        EvalContext resultContext = mock(EvalContext.class);

        when(expression.compute(context)).thenReturn(resultContext);

        // Act
        Iterator result = expression.iterate(context);

        // Assert
        assertNotNull(result);
        assertTrue(result instanceof ValueIterator);
        // Since ValueIterator wraps the context, we verify the behavior indirectly 
        // or ensure the branch was taken.
    }

    @Test
    public void testIterate_ReturnsValueUtilsIterator_WhenResultIsNotEvalContext() {
        // Arrange
        Expression expression = Mockito.mock(Expression.class);
        EvalContext context = mock(EvalContext.class);
        List<String> expectedList = Arrays.asList("a", "b", "c");

        when(expression.compute(context)).thenReturn(expectedList);

        // Act
        Iterator result = expression.iterate(context);

        // Assert
        assertNotNull(result);
        // Verify the iterator content to ensure ValueUtils.iterate was called correctly
        int count = 0;
        while (result.hasNext()) {
            assertEquals(expectedList.get(count++), result.next());
        }
        assertEquals(3, count);
    }

    @Test
    public void testIterate_ReturnsEmptyIterator_WhenResultIsNull() {
        // Arrange
        Expression expression = Mockito.mock(Expression.class);
        EvalContext context = mock(EvalContext.class);

        when(expression.compute(context)).thenReturn(null);

        // Act
        Iterator result = expression.iterate(context);

        // Assert
        assertNotNull(result);
        assertEquals(false, result.hasNext());
    }

    @Test
    public void testIterate_ReturnsSingleObjectIterator_WhenResultIsSingleObject() {
        // Arrange
        Expression expression = Mockito.mock(Expression.class);
        EvalContext context = mock(EvalContext.class);
        String singleValue = "testValue";

        when(expression.compute(context)).thenReturn(singleValue);

        // Act
        Iterator result = expression.iterate(context);

        // Assert
        assertNotNull(result);
        assertTrue(result.hasNext());
        assertEquals(singleValue, result.next());
        assertEquals(false, result.hasNext());
    }
}
